import { Box, Flex, Text } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import { Icon } from "../../../Icon";
import { HandWave } from "../../../Icon/icons";
import { type ConversationEvent, type ConversationEventAction } from "../../../types";
import { bargeInPlayback, formatDuration } from "../../../utils/barge-in";
import { ConversationEventActionButton } from "../../ConversationEventActionButton";
import { useConversationLogSx } from "../useConversationLogSx";

interface BargeInEventProps {
  event: ConversationEvent;
  isSelected: boolean;
  conversationEventActions?: ConversationEventAction[];
}

function playbackSummary(event: ConversationEvent): string {
  const {
    confirmedThroughMs,
    interruptedWord,
    interruptedWordIndex,
    responseWordCount,
    totalAudioDurationMs,
  } = bargeInPlayback(event);

  if (
    interruptedWord !== undefined &&
    interruptedWordIndex !== undefined &&
    responseWordCount !== undefined
  ) {
    return `Interrupted at "${interruptedWord}" (word ${interruptedWordIndex + 1} of ${responseWordCount})`;
  }
  if (confirmedThroughMs !== undefined && totalAudioDurationMs !== undefined) {
    const completion = Math.round((confirmedThroughMs / totalAudioDurationMs) * 100);
    return `Confirmed through ${formatDuration(confirmedThroughMs)} of ${formatDuration(totalAudioDurationMs)} (${completion}%)`;
  }
  if (confirmedThroughMs !== undefined) {
    return `Confirmed through ${formatDuration(confirmedThroughMs)}`;
  }
  if (totalAudioDurationMs !== undefined) {
    return `Response duration ${formatDuration(totalAudioDurationMs)}`;
  }
  return "Playback position unavailable";
}

export const BargeInEvent = forwardRef<HTMLDivElement | null, BargeInEventProps>(
  (props: BargeInEventProps, ref) => {
    const { event, isSelected = false, conversationEventActions, ...otherProps } = props;
    const { hoverableContainerSx, baseMessageSx, iconSx } = useConversationLogSx(isSelected);
    const [isHovered, setIsHovered] = React.useState(false);

    return (
      <Flex
        css={hoverableContainerSx}
        ref={ref}
        tabIndex={0}
        role="button"
        position="relative"
        cursor="pointer"
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        {...otherProps}
      >
        {isHovered && (
          <ConversationEventActionButton event={event} actions={conversationEventActions} />
        )}
        <Box css={baseMessageSx}>
          <Icon icon={HandWave} style={iconSx} />
          <Text textStyle="xs" variant="muted" lineClamp={2} wordBreak="break-all">
            User interrupted playback · {playbackSummary(event)}
          </Text>
        </Box>
      </Flex>
    );
  },
);

BargeInEvent.displayName = "BargeInEvent";
